// Medical Terminology Practice Test 2. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items: building and breaking down terms, with different word parts
// and conditions from Practice Test 1.
import {q, mix} from './q.js';
const EHR='Ehrlich, Medical Terminology for Health Professions', STAN='Stanhope & Turnbull, Introduction to Medical Terminology', TAB='Taber’s Cyclopedic Medical Dictionary';
const WP='Roots, Prefixes, Suffixes, and Combining Forms', BODY='Overview of Body', SKEL='Skeletal', MUS='Muscular', RESP='Respiratory', DIG='Digestive', CV='Cardiovascular & Lymphatic', NERV='Nervous/Special Senses', ENDO='Endocrine', REPRO='Reproductive', INTEG='Integumentary', URIN='Urinary';

export default {
 id:'medical-terminology-2',
 event:'Medical Terminology',
 title:'Practice Test 2',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Ehrlich’s Medical Terminology for Health Professions, Stanhope & Turnbull, and Taber’s Cyclopedic Medical Dictionary',
 plan:[{area:WP,weight:45},{area:BODY,weight:5},{area:SKEL,weight:5},{area:MUS,weight:5},{area:RESP,weight:5},{area:DIG,weight:5},{area:CV,weight:5},{area:NERV,weight:5},{area:ENDO,weight:5},{area:REPRO,weight:5},{area:INTEG,weight:5},{area:URIN,weight:5}],
 questions:mix([
  q(WP,'Which suffix means “surgical repair”?','-plasty',['-pexy','-rrhaphy','-desis'],'C','-pexy is surgical fixation, -rrhaphy is suturing and -desis is binding or fusion.',EHR),
  q(WP,'Which suffix means “suturing”?','-rrhaphy',['-rrhagia','-rrhea','-rrhexis'],'A','-rrhagia is bursting forth of blood, -rrhea is flow or discharge and -rrhexis is rupture.',EHR),
  q(WP,'What does the suffix -malacia mean?','Abnormal softening',['Abnormal hardening','Enlargement','Dilation'],'B','Hardening is -sclerosis, enlargement is -megaly and dilation is -ectasis.',EHR),
  q(WP,'Which prefix means “below” or “deficient”?','hypo-',['hyper-','epi-','supra-'],'D','hyper- means excessive, epi- means above or upon and supra- means above.',EHR),
  q(WP,'What does the combining form crani/o refer to?','Skull',['Rib','Hip','Shoulder blade'],'C','A craniotomy is an incision into the skull. Rib is cost/o, hip is ili/o and shoulder blade is scapul/o.',STAN),
  q(WP,'Which term means “inflammation of many joints”?','Polyarthritis',['Polyneuritis','Panarthritis','Multipleuritis'],'A','poly- means many and arthr/o means joint. Polyneuritis involves many nerves.',EHR),
  q(WP,'In the term angioplasty, what does angi/o mean?','Vessel',['Heart','Valve','Muscle'],'B','angi/o and vas/o refer to vessels; cardi/o is heart and valv/o is valve.',EHR),
  q(WP,'What does the suffix -ptosis mean?','Drooping or sagging',['Spitting','Falling asleep','Swallowing'],'D','Blepharoptosis is a drooping eyelid. -ptysis means spitting, as in hemoptysis.',EHR),
  q(WP,'Which term means “excessive sweating”?','Hyperhidrosis',['Hyperkeratosis','Hypohidrosis','Hydrocephalus'],'A','hidr/o means sweat. Do not confuse it with hydr/o, which means water.',EHR),
  q(WP,'Which combining form means “black”?','melan/o',['leuk/o','erythr/o','cyan/o'],'C','Melanoma is a cancer of pigment cells. leuk/o is white, erythr/o is red and cyan/o is blue.',STAN),
  q(WP,'Which term means “pertaining to under the tongue”?','Sublingual',['Supralingual','Intralingual','Glossectomy'],'B','sub- means under, lingu/o means tongue and -al means pertaining to.',EHR),
  q(WP,'What does the prefix brady- mean?','Slow',['Fast','Difficult','Absent'],'D','tachy- means fast, dys- means difficult and a- or an- means without.',EHR),
  q(WP,'Which term means a visual examination of the inside of a joint?','Arthroscopy',['Arthrogram','Arthroplasty','Arthrolysis'],'A','-scopy is visual examination; -gram is a record and -plasty is surgical repair.',EHR),
  q(WP,'What does the suffix -emesis mean?','Vomiting',['Bleeding','Digestion','Swallowing'],'C','Hematemesis is vomiting blood and hyperemesis is excessive vomiting. Swallowing is -phagia.',EHR),
  q(WP,'Which prefix means “half” or “partial”?','hemi-',['hemo-','hyper-','hetero-'],'B','hemi- and semi- mean half, as in hemiplegia. hem/o and hemat/o refer to blood.',STAN),
  q(WP,'What does the combining form pyel/o refer to?','Renal pelvis',['Pylorus','Pus','Pancreas'],'D','Pyelonephritis is inflammation of the renal pelvis and kidney. py/o means pus.',EHR),
  q(WP,'Which suffix means “pain”?','-algia',['-asthenia','-esthesia','-plegia'],'A','-dynia also means pain. -plegia is paralysis and -esthesia is sensation.',EHR),
  q(WP,'Which term means “cutting into a vein”?','Phlebotomy',['Phlebectomy','Venography','Arteriotomy'],'C','phleb/o means vein and -otomy means cutting into; -ectomy is surgical removal.',EHR),
  q(WP,'What does the prefix ante- mean?','Before',['Against','After','Between'],'B','anti- means against, post- means after and inter- means between.',STAN),
  q(WP,'What does the combining form necr/o mean?','Death',['Nerve','Kidney','New'],'D','Necrosis is tissue death. neur/o is nerve, nephr/o is kidney and neo- is new.',EHR),
  q(WP,'Which term means “a tumor made of fat”?','Lipoma',['Fibroma','Myoma','Chondroma'],'A','lip/o means fat; fibr/o is fiber, my/o is muscle and chondr/o is cartilage.',EHR),
  q(WP,'Which term means “abnormal fear of being in open or public places”?','Agoraphobia',['Claustrophobia','Acrophobia','Photophobia'],'C','agora means marketplace. Claustrophobia is fear of closed spaces; acrophobia is fear of heights.',STAN),
  q(WP,'What does the suffix -stenosis mean?','Narrowing',['Opening','Stone formation','Hardening'],'B','Aortic stenosis is narrowing of the aortic valve opening; spinal stenosis narrows the spinal canal.',EHR),
  q(BODY,'Which term describes a location toward the head or the upper part of a structure?','Superior',['Inferior','Distal','Lateral'],'D','Superior and cephalic mean toward the head; inferior and caudal mean toward the feet.',EHR),
  q(BODY,'The elbow is ______ to the wrist.','Proximal',['Distal','Medial','Superficial'],'A','Proximal means closer to the point of attachment to the trunk; distal is farther away.',EHR),
  q(SKEL,'What is a comminuted fracture?','A bone broken into several pieces',['A break that pierces the skin','A crack on one side of the bone only','A fracture caused by repeated stress'],'C','A compound (open) fracture breaks the skin; a greenstick fracture bends and cracks on one side.',EHR),
  q(SKEL,'Which term means “abnormal increased forward curvature of the lower spine”?','Lordosis',['Kyphosis','Scoliosis','Spondylosis'],'B','Kyphosis is an outward curve of the upper spine, often called hunchback.',EHR),
  q(SKEL,'What is a laminectomy?','Removal of part of a vertebra',['Removal of a knee cartilage','Fusion of two vertebrae','Removal of the kneecap'],'D','The lamina is the posterior arch of a vertebra; removing it relieves pressure on the spinal cord or nerves.',EHR),
  q(MUS,'What is fibromyalgia?','Chronic widespread muscle pain',['A torn tendon','Inflammation of a bursa','Muscle tissue breakdown'],'A','fibr/o means fiber, my/o means muscle and -algia means pain. Bursitis is bursa inflammation.',EHR),
  q(MUS,'Which term describes turning the palm upward?','Supination',['Pronation','Inversion','Eversion'],'C','Pronation turns the palm downward; inversion and eversion describe the sole of the foot.',EHR),
  q(RESP,'Which term means “difficult or labored breathing”?','Dyspnea',['Apnea','Eupnea','Orthopnea'],'B','Apnea is absence of breathing, eupnea is normal breathing and orthopnea is breathing difficulty when lying flat.',EHR),
  q(RESP,'What is a pneumothorax?','Air in the pleural space',['Pus in the pleural space','Blood in the pleural space','Fluid in the alveoli'],'D','Pus is empyema (pyothorax), blood is hemothorax and fluid in alveoli is pulmonary edema.',EHR),
  q(RESP,'Which term describes inflammation of the voice box?','Laryngitis',['Pharyngitis','Tracheitis','Rhinitis'],'A','The larynx is the voice box; the pharynx is the throat and rhin/o is the nose.',EHR),
  q(DIG,'Which term means “difficulty swallowing”?','Dysphagia',['Dysphasia','Dyspepsia','Aphagia'],'C','Dysphasia is difficulty speaking and dyspepsia is indigestion.',EHR),
  q(DIG,'What is cirrhosis?','Chronic scarring of the liver',['Inflammation of the appendix','Stones in the gallbladder','Inflammation of the pancreas'],'B','Cirrhosis often results from long-term alcohol use or hepatitis; the liver loses normal function.',EHR),
  q(CV,'Which term means “an abnormally fast heart rate”?','Tachycardia',['Bradycardia','Arrhythmia','Cardiomegaly'],'D','Tachycardia is generally a resting rate above 100 beats per minute in adults.',EHR),
  q(CV,'What is an embolus?','A clot or mass carried in the bloodstream',['A clot attached to a vessel wall','A weak bulging area in an artery','A narrowed coronary artery'],'A','A thrombus is attached to a vessel wall; when it breaks loose and travels it becomes an embolus.',EHR),
  q(CV,'Which term means “inflammation of a lymph vessel”?','Lymphangitis',['Lymphadenitis','Lymphedema','Lymphoma'],'C','Lymphadenitis is inflammation of a lymph node; lymphedema is swelling from lymph buildup.',EHR),
  q(NERV,'Which term means “paralysis of all four limbs”?','Quadriplegia',['Paraplegia','Hemiplegia','Monoplegia'],'B','Paraplegia affects the lower body, hemiplegia one side and monoplegia one limb.',EHR),
  q(NERV,'What is presbyopia?','Age-related loss of near focusing',['Nearsightedness','Clouding of the lens','Increased eye pressure'],'D','presby/o means old age. Nearsightedness is myopia, lens clouding is cataract and increased pressure is glaucoma.',EHR),
  q(ENDO,'Which gland secretes insulin and glucagon?','Pancreas',['Thyroid','Adrenal','Pituitary'],'A','The pancreatic islets contain beta cells that make insulin and alpha cells that make glucagon.',EHR),
  q(ENDO,'What is hyperthyroidism also commonly called when caused by an autoimmune condition?','Graves disease',['Cushing syndrome','Addison disease','Hashimoto disease'],'C','Hashimoto disease causes hypothyroidism; Cushing and Addison involve the adrenal glands.',EHR),
  q(ENDO,'Which term describes excessive urination caused by a lack of antidiuretic hormone?','Diabetes insipidus',['Diabetes mellitus','Hyperkalemia','Polyphagia'],'B','Without ADH, the kidneys cannot concentrate urine. Polyphagia means excessive hunger.',EHR),
  q(REPRO,'What does the term amenorrhea mean?','Absence of menstruation',['Painful menstruation','Heavy menstruation','Bleeding between periods'],'D','Dysmenorrhea is painful, menorrhagia is heavy and metrorrhagia is bleeding between periods.',EHR),
  q(REPRO,'What is a vasectomy?','Removal of part of the vas deferens',['Removal of the prostate','Removal of a testicle','Repair of the urethra'],'A','Cutting the vas deferens blocks sperm transport and is a form of male sterilization.',EHR),
  q(INTEG,'What is alopecia?','Hair loss',['Excess hair growth','Loss of skin color','Thickened skin'],'C','Excess hair growth is hirsutism; loss of pigment is vitiligo.',EHR),
  q(INTEG,'Which term describes a bruise, a purplish patch of blood under the skin?','Ecchymosis',['Petechiae','Urticaria','Erythema'],'B','Petechiae are pinpoint hemorrhages, urticaria is hives and erythema is redness.',EHR),
  q(INTEG,'Which term means “pertaining to within the skin”?','Intradermal',['Subcutaneous','Transdermal','Epidermal'],'D','Subcutaneous is beneath the skin and transdermal means through the skin.',EHR),
  q(URIN,'Which term means “blood in the urine”?','Hematuria',['Pyuria','Albuminuria','Glycosuria'],'A','Pyuria is pus, albuminuria is protein and glycosuria is sugar in the urine.',EHR),
  q(URIN,'Which term means “scanty urine output”?','Oliguria',['Anuria','Polyuria','Dysuria'],'C','Anuria is no urine output, polyuria is excessive output and dysuria is painful urination.',EHR)
 ],337)
};
